import 'dart:async';import 'package:flutter/material.dart';import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:locallink/core/models/call.dart';import 'package:locallink/core/models/device.dart';import 'package:locallink/features/calls/data/models/call_session.dart';import 'package:locallink/features/calls/domain/call_repository_contract.dart';import 'package:locallink/features/calls/domain/call_gateway.dart';import 'package:locallink/core/diagnostics/app_diagnostics.dart';
final class CallState extends Equatable{final CallSession? session;final List<CallRecord> history;final Map<String,String> deviceNames;final Object? error;const CallState({this.session,this.history=const [],this.deviceNames=const {},this.error});CallState copyWith({CallSession? session,bool clearSession=false,List<CallRecord>? history,Map<String,String>? deviceNames,Object? error,bool clearError=false})=>CallState(session:clearSession?null:(session??this.session),history:history??this.history,deviceNames:deviceNames??this.deviceNames,error:clearError?null:(error??this.error));@override List<Object?>get props=>[session,history,deviceNames,error.toString()];}
final class CallBloc extends Cubit<CallState>{final CallGateway service;final CallRepositoryContract repository;StreamSubscription<CallSession?>? _sessionSub;StreamSubscription<List<CallRecord>>? _historySub;bool _started=false;bool _closed=false;CallBloc({required this.service,required this.repository}):super(const CallState());CallSession? get session=>state.session??service.session;List<CallRecord> get historyItems=>state.history;Map<String,String> get deviceNames=>state.deviceNames;String? get selfDeviceId=>service.selfDeviceId;Object? get error=>state.error;Stream<CallSession?> get sessionStream=>service.sessionStream;Stream<List<CallRecord>> get historyStream=>service.historyStream;void start(){if(_started||_closed)return;_started=true;_sessionSub=service.sessionStream.listen((s){ AppDiagnostics.instance.record('call', s == null ? 'session_cleared' : 'session_state', data:{ if(s!=null) 'state':s.state.name, if(s!=null) 'status':s.direction.name }); emit(state.copyWith(session:s,clearSession:s==null)); });_historySub=service.historyStream.listen((h)=>emit(state.copyWith(history:List.unmodifiable(h))));service.start();}Future<void> refreshHistory()async{try{emit(state.copyWith(clearError:true));emit(state.copyWith(history:await repository.syncHistory(),deviceNames:await repository.loadDeviceNames()));}catch(e){emit(state.copyWith(error:e));}}Future<void> startCall(Device d)async=>_run(()=>service.startCall(d));Future<void> acceptIncoming()async=>_run(service.acceptIncoming);Future<void> rejectIncoming({String reason='rejected'})async=>_run(()=>service.rejectIncoming(reason:reason));Future<void> endCall({String reason='hangup'})async=>_run(()=>service.endCall(reason:reason));Future<void> toggleMute()async=>_run(service.toggleMute);Future<void> toggleSpeaker()async=>_run(service.toggleSpeaker);Future<void> toggleVideo()async=>_run(service.toggleVideo);Future<void> switchCamera()async=>_run(service.switchCamera);void onAppLifecycleState(AppLifecycleState s)=>service.onAppLifecycleState(s);void clearError(){if(state.error!=null)emit(state.copyWith(clearError:true));}Future<void> _run(Future<void> Function() a)async{try{emit(state.copyWith(clearError:true));await a();}catch(e){AppDiagnostics.instance.recordException('call','operation_failed',e,reasonCode:'call_operation_failed');emit(state.copyWith(error:e));rethrow;}}@override Future<void> close()async{if(_closed)return;_closed=true;await _sessionSub?.cancel();await _historySub?.cancel();await service.dispose();return super.close();}}
